  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": "https://cloudquest.vercel.app/en/#website",
      "url": "https://cloudquest.vercel.app/en/",
      "name": "CloudQuest",
      "description": "An interactive platform that teaches cloud engineering by playing.",
      "inLanguage": "en"
    },
    {
      "@type": "Course",
      "name": "CloudQuest — Cloud Engineering RPG",
      "description": "An interactive 8-chapter programme that teaches Linux, networking, Git, AWS, Terraform, Docker, CI/CD, observability and security by typing real commands in a live terminal.",
      "inLanguage": "en",
      "url": "https://cloudquest.vercel.app/en/",
      "provider": { "@type": "Organization", "name": "CloudQuest", "url": "https://cloudquest.vercel.app/" },
      "teaches": ["Linux", "Terminal", "Networking", "Git", "AWS", "Terraform", "Docker", "Kubernetes", "CI/CD", "Cloud Security"],
      "educationalLevel": "Beginner",
      "hasCourseInstance": { "@type": "CourseInstance", "courseMode": "online", "courseWorkload": "PT40H" }
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "I have never used a terminal — can I still start?",
          "acceptedAnswer": { "@type": "Answer", "text": "Yes. CloudQuest is designed for absolute beginners. The first task is typing 'pwd'. Your mentor Nova tells you what to type at every step, and after three wrong attempts shows you the correct command for free. There is also a Terminal 101 tour before you sign in." }
        },
        {
          "@type": "Question",
          "name": "Do I need a real AWS account? Will I have to pay?",
          "acceptedAnswer": { "@type": "Answer", "text": "No. You type the commands in CloudQuest's own terminal; no credit card or cloud account is required. Trying what you learn on a real AWS Free Tier account is recommended but not required." }
        },
        {
          "@type": "Question",
          "name": "How long does it take to become a Cloud Engineer?",
          "acceptedAnswer": { "@type": "Answer", "text": "The curriculum is built around a six-month programme: 8 chapters, 54 quests, 211 hands-on tasks. For someone putting in a few hours a week, 4-6 months is a reasonable range. The game builds muscle memory; interview preparation should be backed by real projects." }
        },
        {
          "@type": "Question",
          "name": "Can I lose my progress, and does it move between devices?",
          "acceptedAnswer": { "@type": "Answer", "text": "Your progress is stored on the server and syncs across all your devices with your account. Verification also happens on the server, so the XP and badges you earn are real: nobody can grant themselves a level from the browser console." }
        },
        {
          "@type": "Question",
          "name": "What topics does it cover?",
          "acceptedAnswer": { "@type": "Answer", "text": "8 chapters: Terminal and Linux, Networking and Git, AWS Core (IAM, EC2, VPC, S3), Infrastructure as Code (Terraform), Containers (Docker), CI/CD, Observability, and Security and Cost. Plus 6 advanced labs: Network Ops, Scripting, Docker Deep Dive, Terraform Pro, Ansible and Kubernetes." }
        }
      ]
    }
  ]
}
